{
  "story": "How can a function call itself without losing its place? Step through sum, which adds its local input to a recursive result. Watch separate frames accumulate, then disappear. Compare the original frame before and after its child returns: its local input survives unchanged.",
  "aha": {
    "stateId": "resume-a",
    "observation": "Each recursive call owns a separate frame; returning removes the newest frame and resumes its caller with preserved locals."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "state-rail",
      "kind": "step-rail",
      "presentation": "Place explanation and instructions above the experiment. Function: sum(n) returns 0 when n = 0; otherwise it returns n + sum(n − 1). Fixed input: sum(2). Assume synchronous calls, integer locals, no optimization, and no errors. The external caller is omitted. Balanced parameter-control budget: zero, excluding navigation and Reset. The rail tracks discrete states, never elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "stack-slots",
      "kind": "fixed-picture",
      "presentation": "Arrange fixed stack slots vertically in declared order, newest position above oldest. Highlighted slots contain live frames; unhighlighted slots are empty. Slot outlines remain visible for comparison. The anchored callout identifies the executing or returning frame.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "frame-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the named frame without covering slot labels. Identify where execution changes; keep numerical values in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "frame-values",
      "kind": "value-readout",
      "presentation": "Align frame rows with their matching stack slots. The return row holds the latest returned value, or none before any return. The final row is the bound status line. Locals and returns are exact, unitless integers without rounding. Each local belongs only to its named frame.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stack-state",
      "kind": "index",
      "items": "variant.states",
      "label": "Call stack state",
      "presentation": "Default to the first state. Previous and Next change stack occupancy, frame execution, locals, and returned-value evidence. Preserve their names when disabled at boundaries. Every state persists until learner action, including resume-a. Use visible focus and keyboard-operable buttons. Reference captures show resume-a."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and fixed-input defaults. Provide an accessible name, visible focus, and keyboard operation."
    }
  ],
